import{z as d,x as s,o as r,c as A,q as i,j as l,D as e,d as m,s as o,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const W=JSON.parse('{"title":"矩阵乘作为一层","description":"","frontmatter":{"title":"矩阵乘作为一层","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/matmul-as-layer.md","filePath":"llm/matmul-as-layer.md","lastUpdated":1791063341000}'),B={name:"llm/matmul-as-layer.md"};function p(h,a,_,u,D,b){const n=s("Mermaid");return r(),A("div",null,[a[2]||(a[2]=i('<h1 id="矩阵乘作为一层" tabindex="-1">矩阵乘作为一层 <a class="header-anchor" href="#矩阵乘作为一层" aria-label="Permalink to &quot;矩阵乘作为一层&quot;">​</a></h1><div class="epigraph"><p>仿射变换把一组输入坐标改写成另一组输出坐标；深度网络的一层，首先是一次可学习的矩阵乘。</p><footer>—— 据 Goodfellow, Bengio &amp; Courville, Deep Learning, 2016 整理</footer></div><p><a href="/llm/tensor-shape-broadcast">张量、形状与广播</a>钉死了轴如何对齐。本课不重讲广播规则。缺口是：对齐之后，把 \\(x\\in\\mathbb{R}^{d_{\\mathrm{in}}}\\) 映到 \\(y\\in\\mathbb{R}^{d_{\\mathrm{out}}}\\) 的基本可学习算子是什么。没有这次矩阵乘，后面的感知机、注意力里的投影、分类头都没有对象。偏置、激活、初始化是后课；这里只把「一层 \\(=\\) 一次 GEMM」钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>形状合法只说明两个数组能相乘，不说明乘完的结果是一层网络。逐元素乘没有把「每个输出坐标都看见全部输入」这件事写进去；卷积把局部窗口摊开之后，核心仍是矩阵乘。缺口因此不是新的形状规则，而是把可学习参数收进一张矩阵 \\(W\\)，使 \\(y\\) 的每一个分量都是 \\(x\\) 的线性组合。</p><p>若把一层写成一堆标量权重的 Python 循环，批维、序列维无法一次交给硬件。框架与加速器为 GEMM 做了几十年优化；大模型里绝大多数浮点运算都落在不同形状的矩阵乘上。本课把这一事实写成定义，而不是写成实现偏好。</p><h3 id="矩阵乘不是逐元素乘" tabindex="-1">矩阵乘不是逐元素乘 <a class="header-anchor" href="#矩阵乘不是逐元素乘" aria-label="Permalink to &quot;矩阵乘不是逐元素乘&quot;">​</a></h3><p>\\((B,n,d)\\) 与另一张同形张量相乘，得到的仍是逐位置缩放，通道之间不混合。线性层要的是：\\(d_{\\mathrm{in}}\\) 被收缩，\\(d_{\\mathrm{out}}\\) 被展开，每个输出通道是输入通道的加权和。形状上看，是 \\((B,n,d_{\\mathrm{in}})\\) 与 \\((d_{\\mathrm{in}},d_{\\mathrm{out}})\\) 的收缩，不是 \\((B,n,d)\\) 与 \\((B,n,d)\\) 的 Hadamard 积。把两种乘法叫成同一个「乘」，后课的投影层会没有对象。</p><p><span class="marginnote">可以把它想成调音台：输入是 \\(d_{\\mathrm{in}}\\) 路音轨，\\(W\\) 的每一行是一组推子设定，输出的每一路都是全部音轨按设定混合出来的新音轨。而「逐元素乘」只是每路单独调音量、彼此永不混合。一个让通道互相「对话」，一个只各自变响变轻——这就是矩阵乘能学到东西、逐元素乘不能的根本原因。</span></p><p><span class="marginnote">公式里常写 \\(y=Wx\\) 或 \\(y=xW^\\top\\)，差别只在 \\(W\\) 按行还是按列存。框架的 Linear 默认右乘 \\(xW^\\top\\)。本课两者等同，后课读代码时先看 \\(W\\) 的形状是 \\((d_{\\mathrm{out}},d_{\\mathrm{in}})\\) 还是反过来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>存储 \\(W\\in\\mathbb{R}^{d_{\\mathrm{out}}\\times d_{\\mathrm{in}}}\\)。单个向量 \\(y=Wx\\)（或 \\(y=xW^\\top\\)）。一批 \\(X\\in\\mathbb{R}^{B\\times d_{\\mathrm{in}}}\\) 则 \\(Y=XW^\\top\\in\\mathbb{R}^{B\\times d_{\\mathrm{out}}}\\)。序列再加一轴：\\(X\\in\\mathbb{R}^{B\\times n\\times d_{\\mathrm{in}}}\\)，矩阵乘作用在最后一维，前两维当批。参数量是 \\(d_{\\mathrm{in}}d_{\\mathrm{out}}\\)，与 \\(B,n\\) 无关：同一张 \\(W\\) 被所有位置共享。</p><p><span class="marginnote">参数量有多吓人：\\(d_{\\mathrm{in}}=d_{\\mathrm{out}}=4096\\) 的一层就有 \\(4096\\times4096\\approx1678\\) 万个参数，FP16 存储约 32 MB。一个几十层、每层多张这样矩阵的模型，参数轻松叠到上百亿——「大模型的参数主要住在矩阵乘里」说的就是这笔账。</span></p><p>这就是全连接层的核心。后课 MLP 的两张投影、注意力里把残差流切成查询键值、语言模型的分类头，都是同一算子换形状。本课不引入偏置向量 \\(b\\)；没有 \\(b\\) 时，过原点的线性映射不能表示平移，那是<a href="/llm/linear-layer-bias">线性层与偏置</a>的缺口。</p>',14)),(r(),l(E,null,{default:e(()=>[o(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%20X%20%E5%BD%A2%E7%8A%B6%20B%20n%20d_in%22%5D%20--%3E%20MM%5B%22%E7%9F%A9%E9%98%B5%E4%B9%98%22%5D%0A%20%20W%5B%22%E6%9D%83%E9%87%8D%20W%20%E5%BD%A2%E7%8A%B6%20d_out%20%E4%B9%98%20d_in%22%5D%20--%3E%20MM%0A%20%20MM%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%20Y%20%E5%BD%A2%E7%8A%B6%20B%20n%20d_out%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[m("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"每个输出神经元规定一组对输入的权重。矩阵乘把「\\(d_{\\mathrm{out}}\\) 组权重同时作用在一批向量上」收成一次核函数。梯度 \\(\\partial L/\\partial W\\) 具有外积结构：输入向量与上游传来的输出梯度相乘，按批与位置求和。后课反向传播会把这一行写成局部规则；本课只需承认：\\(W\\) 的每个元素都有明确的对损失的导数，因为映射对 \\(W\\) 是线性的。",-1)),a[5]||(a[5]=t("p",null,"共享同一张 \\(W\\) 是归纳偏置：序列里第 \\(1\\) 个位置和第 \\(n\\) 个位置用同一组坐标变换。位置之间的差异必须由输入内容（以及后课才出现的位置编码）提供，而不是由「每一列一套 \\(W\\)」提供。这与卷积共享核是同一类节省，只是这里的「窗口」是整个特征维。",-1)),a[6]||(a[6]=t("p",null,[t("span",{class:"marginnote"},"为什么 \\(W\\) 必须全位置共享？若每个位置各配一张 \\(W\\)，参数量要再乘上序列长度 \\(n\\)，长文本直接放不下；共享还保证「同一个词无论出现在第 1 个还是第 1000 个位置，都走同一套变换」，位置差异交给位置编码处理——这也是 Transformer 能整句并行计算的隐性前提之一。")],-1)),(r(),l(E,null,{default:e(()=>[o(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20X2%5B%22X%20%E7%9A%84%E7%AC%AC%202%20%E8%A1%8C%EF%BC%9A%E9%95%BF%20d_in%22%5D%20--%3E%20DOT%5B%22%E7%82%B9%E7%A7%AF%EF%BC%9A%E9%80%90%E5%85%83%E7%B4%A0%E7%9B%B8%E4%B9%98%E5%86%8D%E6%B1%82%E5%92%8C%22%5D%0A%20%20W3%5B%22W%20%E7%9A%84%E7%AC%AC%203%20%E8%A1%8C%EF%BC%9A%E9%95%BF%20d_in%22%5D%20--%3E%20DOT%0A%20%20DOT%20--%3E%20Y23%5B%22%E5%A1%AB%E5%85%A5%20Y%20%E7%AC%AC%202%20%E8%A1%8C%E7%AC%AC%203%20%E5%88%97%22%5D%0A%20%20Y23%20--%3E%20PAIRS%5B%22%E5%AF%B9%E5%85%A8%E9%83%A8%E8%A1%8C%E9%85%8D%E5%AF%B9%E9%87%8D%E5%A4%8D%E8%BF%99%E4%B8%80%E6%AD%A5%22%5D%0A%20%20PAIRS%20--%3E%20Y%5B%22%E5%A1%AB%E6%BB%A1%E6%95%B4%E4%B8%AA%E8%BE%93%E5%87%BA%20Y%22%5D%0A%20%20Y%20--%3E%20SHARE%5B%22W%20%E5%85%A8%E7%A8%8B%E4%B8%8D%E5%A4%8D%E5%88%B6%EF%BC%9AB%20%E4%B9%98%20n%20%E4%B8%AA%E4%BD%8D%E7%BD%AE%E5%85%B1%E7%94%A8%E5%90%8C%E4%B8%80%E5%BC%A0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[m(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论偏置、激活、初始化方差，也不把卷积展开成 im2col。低秩分解、混合专家里的路由，都还是同一张稠密 \\(W\\) 的变体，不在这里展开。下一课<a href="/llm/norm-cosine-projection">范数、余弦与投影</a>不问如何变换空间，而问变换之后如何度量两个向量有多像。后课默认：看见「一层线性」，就写成一次对最后一维的矩阵乘，参数量 \\(d_{\\mathrm{in}}d_{\\mathrm{out}}\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线性层的核心是 \\(y=xW^\\top\\)；批与序列维沿前面的轴并行，最后一维被收缩。</li><li>参数量 \\(d_{\\mathrm{in}}d_{\\mathrm{out}}\\)，与批大小、长度无关；同一 \\(W\\) 被各位置共享。</li><li>这不是逐元素乘：通道混合靠收缩 \\(d_{\\mathrm{in}}\\)。</li><li>注意力与 MLP 的投影、分类头，都是这一算子换形状。</li><li>出处：Goodfellow et al., Deep Learning, 2016，前馈网络中的仿射变换。</li></ul>',4))])}const C=d(B,[["render",p]]);export{W as __pageData,C as default};
